import {test} from 'node:test';
import assert from 'node:assert/strict';
import {reconcileRecords,resolveReview,mergeRecords} from './reconcile.js';
import {parseMail,samples,sumMonth,PARSER_VERSION} from './parser.js';
const pending={id:'mail-a',account:'gmail:a',status:'review',reason:'円換算待ち',mode:'credit',merchant:'TEST SHOP',date:'2026-08-12T19:09:00+09:00',month:'2026-08',currency:'KRW',originalAmount:'7500.00',reference:'transaction-1'};
const counted={id:'mail-b',account:'gmail:a',status:'accepted',kind:'settlement',mode:'credit',merchant:'TEST SHOP',date:'2026-08-12T00:00:00+09:00',month:'2026-08',currency:'JPY',amount:680,reference:'transaction-1'};
test('同一取引を特定した場合だけ旧通知を除外し、円明細だけを集計する',()=>{const rows=reconcileRecords([pending,counted]);assert.equal(rows[0].status,'excluded');assert.equal(rows[0].resolvedBy,'mail-b');assert.equal(rows[0].resolution,'auto');assert.match(rows[0].reason,/680円/);assert.equal(sumMonth(rows,'2026-08'),680);assert.deepEqual(reconcileRecords(rows),rows);});
test('取引番号が一致する計上済みJPY利用通知でも外貨通知を解決する',()=>{assert.equal(reconcileRecords([pending,{...counted,kind:'authorization'}])[0].status,'excluded');assert.equal(reconcileRecords([pending,{...counted,currency:'USD'}])[0].status,'review');});
test('参照番号なし・別口座・別モード・別利用日・別店舗を誤照合しない',()=>{for(const target of [{...counted,reference:null},{...counted,reference:'another'},{...counted,account:'gmail:b'},{...counted,mode:'debit'},{...counted,date:'2026-08-13T00:00:00+09:00'},{...counted,merchant:'OTHER SHOP'}])assert.equal(reconcileRecords([pending,target])[0].status,'review');});
test('対応候補が複数、または同じ明細に複数通知が対応する場合は保留する',()=>{assert.equal(reconcileRecords([pending,counted,{...counted,id:'mail-c'}])[0].status,'review');assert.equal(reconcileRecords([pending,{...pending,id:'mail-c'},counted])[0].status,'review');});
test('日付と店舗だけのUber通知を勝手に照合しない',()=>{assert.equal(reconcileRecords([{...pending,reference:null,merchant:'UBER * PENDING'},{...counted,reference:null,merchant:'UBER *TRIP HELP.UBER.COM'}])[0].status,'review');});
test('確認済み対応は繰り返し取得しても維持し、合計は変えない',()=>{const resolved=resolveReview(pending,counted);const rows=mergeRecords([resolved,counted],[{...pending,parserVersion:PARSER_VERSION}]);assert.equal(rows[0].status,'excluded');assert.equal(rows[0].resolution,'manual');assert.equal(sumMonth(rows,'2026-08'),680);});
test('対応先が消失・未計上なら要確認へ戻る',()=>{assert.equal(reconcileRecords([resolveReview(pending,counted)])[0].status,'review');assert.throws(()=>resolveReview(pending,{...counted,status:'review'}));assert.throws(()=>resolveReview(pending,{...counted,account:'gmail:b'}));});
test('自動解決の取消しは再取り込みでも維持する',()=>{const manualReview={...pending,autoResolveDisabled:true};assert.equal(reconcileRecords([manualReview,counted])[0].status,'review');assert.equal(mergeRecords([manualReview,counted],[{...pending,parserVersion:PARSER_VERSION}])[0].status,'review');});
test('旧パーサーの要確認は再解析されJPY支出となり、再取り込みで増えない',()=>{const mail={...samples[0],body:samples[0].body.replace('786円','786.00 JPY')};const incoming={...parseMail(mail),id:'jpy',account:'gmail:a',parserVersion:PARSER_VERSION};const old={id:'jpy',account:'gmail:a',status:'review',reason:'金額を確認できません'};const rows=mergeRecords([old],[incoming]);assert.equal(sumMonth(rows,'2026-11'),786);assert.equal(mergeRecords(rows,[incoming]).length,1);});
test('承認番号のある同額円通知は解決し、異額・負数は要確認に残す',()=>{const p={...pending,currency:'JPY',reportedAmount:680,reference:null,approval:'123456'};const t={...counted,reference:null,approval:'123456'};assert.equal(reconcileRecords([p,t])[0].status,'excluded');assert.equal(reconcileRecords([{...p,reportedAmount:700},t])[0].status,'review');assert.equal(reconcileRecords([{...p,reportedAmount:undefined,originalAmount:'-100'},t])[0].status,'review');});
test('請求・到達通知は対象外と明示し、利用明細は円建てでも照合待ちとする',()=>{for(const subject of ['お支払い金額のお知らせ','一定金額到達のお知らせ【三井住友カード】'])assert.equal(parseMail({...samples[0],subject}).status,'excluded');const r=parseMail({...samples[0],subject:'ご利用明細のお知らせ【三井住友カード】',body:samples[0].body.replace('2026/11/04 19:53','2026/11/04')});assert.equal(r.status,'review');assert.equal(r.reportedAmount,786);assert.equal(r.datePrecision,'day');assert.equal(sumMonth([r],'2026-11'),0);});
test('負のデビット通知は金額を保持し、支出にも自動解決にも含めない',()=>{const r=parseMail({...samples[1],body:samples[1].body.replace('1,000円','-100円')});assert.equal(r.status,'review');assert.equal(r.originalAmount,'-100');assert.match(r.reason,/返金/);});
